const items = $input.all();
const out = [];
for (const item of items) {
  const raw = item.json || {};
  const src = (raw.body && typeof raw.body === "object") ? raw.body : raw;
  const isWhatsApp = raw.messaging_product === "whatsapp" || Array.isArray(raw.messages) || Array.isArray(raw.statuses);
  const isChat = raw.chatInput !== undefined;
  const isSlack = !isWhatsApp && !isChat && Boolean(raw.channel) && Boolean(raw.ts || raw.event_ts) && (raw.type === "app_mention" || raw.type === "message" || Boolean(raw.team) || Boolean(raw.client_msg_id));

  let channel = "webhook";
  let question = "";
  let sessionId = "";
  let requestedBy = "";
  let slackChannel = "";
  let slackThreadTs = "";
  let waPhoneNumberId = "";
  let waFrom = "";
  let passed = true;
  let isSecurityThreat = false;
  let httpCode = 200;
  let blockReason = "";

  if (isSlack) {
    if (raw.bot_id || raw.subtype === "bot_message" || raw.subtype === "message_changed" || raw.subtype === "message_deleted") {
      continue;
    }
    channel = "slack";
    slackChannel = String(raw.channel || "").trim();
    slackThreadTs = String(raw.thread_ts || raw.ts || "").trim();
    requestedBy = String(raw.user || "Slack User").trim();
    sessionId = "slack-" + slackChannel + "-" + (raw.thread_ts || raw.user || "main");
    question = String(raw.text || "").replace(/<@[A-Z0-9]+>/g, "").trim();
  } else if (isWhatsApp) {
    const waMsg = Array.isArray(raw.messages) ? raw.messages[0] : null;
    if (!waMsg) {
      continue;
    }
    channel = "whatsapp";
    waPhoneNumberId = String(raw.metadata?.phone_number_id || "").trim();
    waFrom = String(waMsg.from || raw.contacts?.[0]?.wa_id || "").trim();
    requestedBy = String(raw.contacts?.[0]?.profile?.name || waFrom || "WhatsApp User").trim();
    sessionId = "whatsapp-" + waFrom;
    if (waMsg.type !== "text") {
      passed = false;
      httpCode = 400;
      blockReason = "Text questions only on WhatsApp. Please send a plain-English sales, inventory, or order question.";
    } else {
      question = String(waMsg.text?.body || "").trim();
    }
  } else if (isChat) {
    channel = "web_chat";
    question = String(src.chatInput || "").trim();
    sessionId = String(src.sessionId || src.session_id || "sales-bi-" + Date.now()).trim();
    requestedBy = String(src.requested_by || src.user || "Chat User").trim();
  } else {
    channel = "webhook";
    question = String(src.question || src.query || src.message || "").trim();
    sessionId = String(src.sessionId || src.session_id || "sales-bi-" + Date.now()).trim();
    requestedBy = String(src.requested_by || src.user || "API Client").trim();
  }

  if (passed) {
    if (!question) {
      passed = false;
      httpCode = 400;
      blockReason = "Missing question. Send a plain-English sales, inventory, or order question.";
    } else if (question.length > 500) {
      passed = false;
      httpCode = 400;
      blockReason = "Question exceeds 500-character limit. Please ask a concise analytics question.";
    } else {
      const threatPattern = /(\b(drop\s+table|delete\s+from|truncate\s+table|alter\s+table|insert\s+into|update\s+\w+\s+set|grant\s+|revoke\s+|pg_sleep|xp_cmdshell|union\s+select)\b|--\s*$|;\s*(drop|delete|update|insert|alter)|ignore\s+(all\s+)?previous\s+instructions|reveal\s+(your\s+)?system\s+prompt|bypass\s+guardrails)/i;
      if (threatPattern.test(question)) {
        passed = false;
        isSecurityThreat = true;
        httpCode = 403;
        blockReason = "Blocked by Input Security Guard: destructive SQL or prompt-injection pattern detected. Read-only retail analytics only.";
      }
    }
  }

  out.push({
    json: {
      channel,
      session_id: sessionId,
      requested_by: requestedBy,
      question,
      slack_channel: slackChannel,
      slack_thread_ts: slackThreadTs,
      wa_phone_number_id: waPhoneNumberId,
      wa_from: waFrom,
      passed_preflight: passed,
      is_security_threat: isSecurityThreat,
      http_code: httpCode,
      block_reason: blockReason,
      received_at: new Date().toISOString()
    }
  });
}
return out;

const req = $("Normalize & Input Guard").item.json || {};
const raw = $input.item.json || {};
const plan = (raw.output && typeof raw.output === "object") ? raw.output : raw;
const allowedDatasets = ["store_inventory", "orders"];
const allowedAnalysis = ["kpi_summary", "group_by", "top_n", "bottom_n", "filter_list", "stockout_risk", "slow_movers", "order_status_breakdown"];
const allowedCols = {
  store_inventory: ["store_id", "store_name", "sku_id", "product_name", "category", "size", "stock_qty", "reorder_point", "units_sold_7d", "revenue_7d", "days_of_cover", "updated_at"],
  orders: ["order_id", "customer_name", "item_summary", "order_status", "tracking_number", "estimated_delivery", "store_location", "created_at"]
};
const allowedMetrics = ["revenue_7d", "units_sold_7d", "stock_qty", "days_of_cover", "avg_selling_price", "order_count"];
const allowedAggs = ["sum", "avg", "count", "min", "max"];
const allowedOps = ["contains", "eq", "neq", "gt", "gte", "lt", "lte"];
const intent = String(plan.intent || "out_of_scope").trim().toLowerCase();
const sql = String(plan.sql_preview || "").trim();
const dataset = allowedDatasets.includes(plan.dataset) ? plan.dataset : "store_inventory";
let allowed = true;
let isSecurityThreat = false;
let httpCode = 200;
let blockReason = "";
if (intent === "unsafe_request") {
  allowed = false;
  isSecurityThreat = true;
  httpCode = 403;
  blockReason = String(plan.refusal_reason || "Unsafe or mutating database request blocked. Only read-only retail analytics are permitted.");
} else if (intent === "out_of_scope") {
  allowed = false;
  httpCode = 400;
  blockReason = String(plan.refusal_reason || "I can only answer retail sales, inventory, SKU performance, and order analytics questions.");
} else if (sql) {
  const cleanedSql = sql.replace(/;+\s*$/, "");
  const forbiddenSql = /\b(insert|update|delete|drop|alter|truncate|create|grant|revoke|copy|execute|pg_sleep|customer_contact)\b/i;
  const multiStmt = cleanedSql.includes(";");
  const startsSelect = /^(select|with)\b/i.test(cleanedSql);
  if (!startsSelect || forbiddenSql.test(cleanedSql) || multiStmt) {
    allowed = false;
    isSecurityThreat = true;
    httpCode = 403;
    blockReason = "SQL Security Gate blocked query: only single read-only SELECT queries over approved retail columns are permitted.";
  }
}
const validCols = allowedCols[dataset];
const rawFilters = Array.isArray(plan.filters) ? plan.filters : [];
const cleanFilters = rawFilters.filter(f => f && validCols.includes(String(f.column || "")) && allowedOps.includes(String(f.operator || "contains").toLowerCase())).map(f => ({ column: String(f.column), operator: String(f.operator || "contains").toLowerCase(), value: f.value }));
const groupBy = (plan.group_by && validCols.includes(plan.group_by)) ? plan.group_by : "none";
const analysisType = allowedAnalysis.includes(plan.analysis_type) ? plan.analysis_type : "kpi_summary";
const metric = allowedMetrics.includes(plan.metric) ? plan.metric : (dataset === "orders" ? "order_count" : "revenue_7d");
const aggregation = allowedAggs.includes(plan.aggregation) ? plan.aggregation : "sum";
const sortOrder = plan.sort_order === "asc" ? "asc" : "desc";
const limit = Math.max(1, Math.min(50, Math.round(Number(plan.limit) || 10)));
return {
  json: {
    channel: req.channel,
    session_id: req.session_id,
    requested_by: req.requested_by,
    question: req.question,
    slack_channel: req.slack_channel || "",
    slack_thread_ts: req.slack_thread_ts || "",
    wa_phone_number_id: req.wa_phone_number_id || "",
    wa_from: req.wa_from || "",
    allowed,
    is_security_threat: isSecurityThreat,
    http_code: httpCode,
    block_reason: blockReason,
    intent,
    dataset,
    analysis_type: analysisType,
    group_by: groupBy,
    metric,
    aggregation,
    sort_order: sortOrder,
    limit,
    filters: cleanFilters,
    sql_preview: sql
  }
};

const gate = $("Query Security Gate").first().json || {};
const rawRows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const dataset = gate.dataset || "store_inventory";
const filters = Array.isArray(gate.filters) ? gate.filters : [];
const limit = Number(gate.limit) || 10;
const sortOrder = gate.sort_order === "asc" ? 1 : -1;
const metric = gate.metric || (dataset === "orders" ? "order_count" : "revenue_7d");
const analysisType = gate.analysis_type || "kpi_summary";
const groupBy = gate.group_by || "none";
const sanitizedRows = rawRows.map(r => {
  const copy = Object.assign({}, r);
  delete copy.customer_contact;
  if (dataset === "store_inventory") {
    copy.stock_qty = Number(copy.stock_qty) || 0;
    copy.reorder_point = Number(copy.reorder_point) || 0;
    copy.units_sold_7d = Number(copy.units_sold_7d) || 0;
    copy.revenue_7d = Number(copy.revenue_7d) || 0;
    copy.days_of_cover = Number(copy.days_of_cover) || 0;
    copy.avg_selling_price = copy.units_sold_7d > 0 ? Math.round(copy.revenue_7d / copy.units_sold_7d) : 0;
  }
  return copy;
});
const matchesFilter = (row, f) => {
  const val = row[f.column];
  if (val === undefined || val === null) return false;
  const op = f.operator || "contains";
  if (op === "contains") return String(val).toLowerCase().includes(String(f.value).toLowerCase());
  if (op === "eq") return String(val).toLowerCase() === String(f.value).toLowerCase();
  if (op === "neq") return String(val).toLowerCase() !== String(f.value).toLowerCase();
  const numVal = Number(val);
  const numTarget = Number(f.value);
  if (op === "gt") return numVal > numTarget;
  if (op === "gte") return numVal >= numTarget;
  if (op === "lt") return numVal < numTarget;
  if (op === "lte") return numVal <= numTarget;
  return true;
};
let filtered = sanitizedRows.filter(r => filters.every(f => matchesFilter(r, f)));
if (analysisType === "stockout_risk" && dataset === "store_inventory") {
  filtered = filtered.filter(r => r.stock_qty <= r.reorder_point || r.days_of_cover < 5);
} else if (analysisType === "slow_movers" && dataset === "store_inventory") {
  filtered = filtered.filter(r => r.days_of_cover > 30 || r.units_sold_7d <= 1);
}
let grandTotals = {};
let resultRows = [];
if (dataset === "store_inventory") {
  const totalRev = filtered.reduce((s, r) => s + r.revenue_7d, 0);
  const totalUnits = filtered.reduce((s, r) => s + r.units_sold_7d, 0);
  const totalStock = filtered.reduce((s, r) => s + r.stock_qty, 0);
  const stockoutCount = filtered.filter(r => r.stock_qty <= r.reorder_point || r.days_of_cover < 5).length;
  const slowMoverCount = filtered.filter(r => r.days_of_cover > 30 || r.units_sold_7d <= 1).length;
  grandTotals = {
    rows_scanned: sanitizedRows.length,
    rows_matched: filtered.length,
    total_revenue_7d_inr: Math.round(totalRev),
    total_units_sold_7d: totalUnits,
    total_stock_qty: totalStock,
    overall_asp_inr: totalUnits > 0 ? Math.round(totalRev / totalUnits) : 0,
    stockout_risk_skus: stockoutCount,
    slow_mover_skus: slowMoverCount
  };
  const shouldGroup = groupBy !== "none" && (analysisType === "group_by" || analysisType === "top_n" || analysisType === "bottom_n");
  if (shouldGroup) {
    const buckets = {};
    for (const r of filtered) {
      const key = String(r[groupBy] || "Unknown");
      if (!buckets[key]) buckets[key] = { [groupBy]: key, revenue_7d: 0, units_sold_7d: 0, stock_qty: 0, days_of_cover_sum: 0, sku_count: 0 };
      buckets[key].revenue_7d += r.revenue_7d;
      buckets[key].units_sold_7d += r.units_sold_7d;
      buckets[key].stock_qty += r.stock_qty;
      buckets[key].days_of_cover_sum += r.days_of_cover;
      buckets[key].sku_count += 1;
    }
    resultRows = Object.values(buckets).map(b => ({
      [groupBy]: b[groupBy],
      revenue_7d: Math.round(b.revenue_7d),
      revenue_share_pct: totalRev > 0 ? Number(((b.revenue_7d / totalRev) * 100).toFixed(1)) : 0,
      units_sold_7d: b.units_sold_7d,
      stock_qty: b.stock_qty,
      avg_selling_price: b.units_sold_7d > 0 ? Math.round(b.revenue_7d / b.units_sold_7d) : 0,
      days_of_cover: Number((b.days_of_cover_sum / b.sku_count).toFixed(1)),
      sku_count: b.sku_count
    }));
  } else {
    resultRows = filtered.map(r => ({
      store_name: r.store_name,
      sku_id: r.sku_id,
      product_name: r.product_name,
      category: r.category,
      size: r.size,
      revenue_7d: r.revenue_7d,
      units_sold_7d: r.units_sold_7d,
      stock_qty: r.stock_qty,
      reorder_point: r.reorder_point,
      days_of_cover: r.days_of_cover,
      avg_selling_price: r.avg_selling_price
    }));
  }
  const sortField = analysisType === "stockout_risk" ? "days_of_cover" : (analysisType === "slow_movers" ? "days_of_cover" : metric);
  const dir = analysisType === "stockout_risk" ? 1 : (analysisType === "slow_movers" ? -1 : (analysisType === "bottom_n" ? 1 : sortOrder));
  resultRows.sort((a, b) => ((Number(a[sortField]) || 0) - (Number(b[sortField]) || 0)) * dir);
  resultRows = resultRows.slice(0, limit);
} else {
  const statusCounts = {};
  for (const r of filtered) {
    const st = String(r.order_status || "Unknown");
    statusCounts[st] = (statusCounts[st] || 0) + 1;
  }
  grandTotals = { rows_scanned: sanitizedRows.length, rows_matched: filtered.length, status_counts: statusCounts };
  if (analysisType === "order_status_breakdown" || (analysisType === "group_by" && groupBy !== "none")) {
    const col = groupBy !== "none" ? groupBy : "order_status";
    const buckets = {};
    for (const r of filtered) {
      const key = String(r[col] || "Unknown");
      buckets[key] = (buckets[key] || 0) + 1;
    }
    resultRows = Object.entries(buckets).map(([k, count]) => ({
      [col]: k,
      order_count: count,
      share_pct: filtered.length > 0 ? Number(((count / filtered.length) * 100).toFixed(1)) : 0
    })).sort((a, b) => (a.order_count - b.order_count) * sortOrder).slice(0, limit);
  } else {
    resultRows = filtered.slice(0, limit).map(r => ({
      order_id: r.order_id,
      customer_name: r.customer_name,
      item_summary: r.item_summary,
      order_status: r.order_status,
      store_location: r.store_location,
      estimated_delivery: r.estimated_delivery
    }));
  }
}
return [{
  json: {
    channel: gate.channel,
    session_id: gate.session_id,
    requested_by: gate.requested_by,
    question: gate.question,
    slack_channel: gate.slack_channel || "",
    slack_thread_ts: gate.slack_thread_ts || "",
    wa_phone_number_id: gate.wa_phone_number_id || "",
    wa_from: gate.wa_from || "",
    dataset,
    analysis_type: analysisType,
    sql_preview: gate.sql_preview,
    grand_totals: grandTotals,
    result_rows: resultRows,
    row_count: resultRows.length,
    computed_at: new Date().toISOString()
  }
}];

const j = $input.item.json || {};
const reason = String(j.block_reason || "Request blocked by read-only BI guardrails.").trim();
const isThreat = Boolean(j.is_security_threat);
const httpCode = Number(j.http_code) || (isThreat ? 403 : 400);
const chatOutput = (isThreat ? "🛡️ **Blocked by Read-Only Security Guard:** " : "ℹ️ ") + reason + "\n\nTry asking something like: *Which store had the highest 7-day revenue?* or *Show SKUs at stockout risk.*";
const messagingOutput = ((isThreat ? "🛡️ *Blocked by Read-Only Security Guard:* " : "ℹ️ ") + reason + "\n\nTry asking: _Which store had the highest 7-day revenue?_ or _Show SKUs at stockout risk._").slice(0, 4000);
return {
  json: {
    ok: false,
    status: isThreat ? "blocked_security_guardrail" : "rejected_invalid_or_out_of_scope",
    http_code: httpCode,
    is_security_threat: isThreat,
    channel: j.channel || "webhook",
    session_id: j.session_id || "",
    requested_by: j.requested_by || "Unknown",
    question: j.question || "",
    slack_channel: j.slack_channel || "",
    slack_thread_ts: j.slack_thread_ts || "",
    wa_phone_number_id: j.wa_phone_number_id || "",
    wa_from: j.wa_from || "",
    reason,
    output: chatOutput,
    slack_text: messagingOutput,
    whatsapp_text: messagingOutput
  }
};

