const engine = $("Deterministic Analytics Engine").first().json || {};
const answer = String($input.item.json.output || "No summary generated.").trim();
const messagingFormatted = answer.replace(/\*\*(.+?)\*\*/g, "*$1*");
const slackText = messagingFormatted + "\n\n_Verified SQL Preview:_\n```" + (engine.sql_preview || "N/A") + "```";
const whatsappText = (messagingFormatted + "\n\n_Dataset: " + engine.dataset + " · Rows matched: " + (engine.grand_totals?.rows_matched ?? engine.row_count) + "_").slice(0, 4000);
return {
  json: {
    ok: true,
    status: "answered",
    channel: engine.channel,
    session_id: engine.session_id,
    question: engine.question,
    slack_channel: engine.slack_channel || "",
    slack_thread_ts: engine.slack_thread_ts || "",
    wa_phone_number_id: engine.wa_phone_number_id || "",
    wa_from: engine.wa_from || "",
    dataset: engine.dataset,
    analysis_type: engine.analysis_type,
    answer,
    output: answer,
    slack_text: slackText,
    whatsapp_text: whatsappText,
    sql_preview: engine.sql_preview,
    grand_totals: engine.grand_totals,
    result_rows: engine.result_rows,
    row_count: engine.row_count,
    computed_at: engine.computed_at
  }
};

